/** The public chart state: config keys, visible keys and visibility requests. */
export function useChartRoot(): ChartRootState {
  const state = inject(ChartRootKey, null);
  if (!state) throw new Error("Chart parts must be rendered inside Chart.Root.");
  return state;
}

export function useOptionalChartRootInternal(): ChartRootInternalState | null {
  return inject(ChartRootInternalKey, null);
}

export function useChartRootInternal(): ChartRootInternalState {
  const state = inject(ChartRootInternalKey, null);
  if (!state) throw new Error("Chart parts must be rendered inside Chart.Root.");
  return state;
}

